import { normalizeFileChangeList } from './turn-file-changes.mjs'
import { normalizeProviderCommandOutput } from './provider-command-output.mjs'

function formatProviderToolOutputDetail(toolName = '', output = null, translate = (_key, fallback) => fallback) {
  if (toolName === 'image_generation' && (output?.result || output?.resultAvailable === true)) {
    return translate(
      'core:executionStream.bridge.providerTool.imageGenerated',
      'Image generated by OpenAI provider tool.',
    )
  }
  if (toolName === 'code_interpreter' && Array.isArray(output?.outputs)) {
    return output.outputs.map((row) => {
      if (row?.type === 'logs') return String(row.logs || '')
      if (row?.type === 'image') return `image: ${String(row.url || '')}`
      return ''
    }).filter(Boolean).join('\n').slice(0, 2200)
  }
  try {
    return typeof output === 'string' ? output : JSON.stringify(output)
  } catch {
    return String(output ?? '')
  }
}

export function buildProviderToolOutputActivity(payload = {}, translate = (_key, fallback) => fallback) {
  const providerToolName = String(payload?.toolName || '').trim()
  const output = payload?.output
  const commandOutput = normalizeProviderCommandOutput(payload)
  const toolName = commandOutput?.toolName || providerToolName
  const toolCallId = String(payload?.toolCallId || '').trim()
  const turnId = String(payload?.turnId || '').trim()
  const isError = commandOutput?.isError === true || payload?.isError === true
    || Boolean(output && typeof output === 'object' && !Array.isArray(output) && (
      Object.hasOwn(output, 'failure')
      || output.success === false
      || ['failed', 'error', 'cancelled'].includes(String(output.status || '').trim().toLowerCase())
      || (Number.isFinite(Number(output.exitCode)) && Number(output.exitCode) !== 0)
    ))
  const normalizedFileChanges = providerToolName === 'file_change'
    ? normalizeFileChangeList(output, { defaultSource: 'file_change' })
    : []
  const suppliedToolInput = payload?.toolInput && typeof payload.toolInput === 'object'
    ? payload.toolInput
    : null
  const toolInput = commandOutput?.toolInput || suppliedToolInput
  const detail = commandOutput?.detail
    ?? formatProviderToolOutputDetail(providerToolName, output, translate)
  return {
    ...(toolCallId && turnId ? { id: `provider_tool:${turnId}:${toolCallId}` } : {}),
    type: 'result',
    threadId: payload?.threadId,
    turnId: payload?.turnId,
    eventKind: 'provider_tool_output',
    providerId: payload?.providerId,
    model: payload?.model,
    toolName,
    ...(toolInput ? { toolInput } : {}),
    ...(output !== undefined ? { output } : {}),
    ...(toolCallId ? { stepId: toolCallId } : {}),
    label: translate(
      'core:executionStream.bridge.providerTool.output',
      'Provider tool output: {{toolName}}',
      { toolName: toolName || 'tool' },
    ),
    detail: String(detail).slice(0, 2200),
    isError,
    ...(Number.isFinite(commandOutput?.exitCode) ? { exitCode: commandOutput.exitCode } : {}),
    ...(Number.isFinite(commandOutput?.durationMs) ? { durationMs: commandOutput.durationMs } : {}),
    ...(normalizedFileChanges.length > 0
      ? { fileChanges: normalizedFileChanges, fileChange: normalizedFileChanges[0] }
      : {}),
  }
}
